const E = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL = value => { const s=String(value ?? '').trim(); return /^(?:\/(?!\/)|https?:\/\/)/i.test(s) ? s : ''; };
const asset = value => { const s=safeURL(value); if (!s) return ''; if (!/^https?:\/\/cdn\.imweb\.me\//i.test(s)) return s; const file=s.split(/[?#]/)[0].split('/').pop(); return file ? '/assets/'+encodeURIComponent(decodeURIComponentSafe(file)) : ''; };
function decodeURIComponentSafe(s) { try { return decodeURIComponent(s); } catch { return s; } }
const arrow = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
