function postCategory(value) {
 const s=String(value || '').replace(/^\/+|\/+$/g,'').toLowerCase();
 const aliases={'공지사항':'notice','공지':'notice','소식':'notice','community':'notice','자료실':'archive','정책자료':'archive','포럼갤러리':'forumgallery','gallery':'forumgallery','뉴스클리핑':'news','뉴스':'news','행사홍보':'event','행사':'event','미디어룸':'mediaroom','media':'mediaroom','재정보고':'finance'};
 return categoryNames[s] ? s : (aliases[s] || s);
}
function dateLabel(value) { const s=String(value||''); const m=s.match(/^(\d{4})[-./](\d{1,2})[-./](\d{1,2})/); return m ? `${m[1]}.${m[2].padStart(2,'0')}.${m[3].padStart(2,'0')}` : ''; }
function plain(value) { return String(value||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim(); }
function groupFor(route) { return groups.find(g=>g.path===route || g.items.some(([p])=>p===route)); }
function button(href,text,kind='solid') { return `<a class="btn btn-${kind}" href="${E(safeURL(href))}"><span>${E(text)}</span>${arrow}</a>`; }
function brand() { return `<a class="brand brand-original" href="/" aria-label="대한민국 ESG정원정책포럼 홈"><img src="/assets/8d2ffcf55fb09.png" alt="ESG정원정책포럼 ESG Garden Policy Forum" width="327" height="72"></a>`; }
