 '<svg viewBox="0 0 80 80" fill="none" aria-hidden="true"><path d="m40 8 27 11v20c0 16-13 27-27 33C26 66 13 55 13 39V19L40 8Z" stroke="currentColor" stroke-width="1.5"/><path d="m28 40 8 8 17-19" stroke="currentColor" stroke-width="1.5"/><path d="m24 24 16-7 16 7" stroke="currentColor" stroke-width="1.5"/></svg>'
