const script = `
(function(){
 const sidebarNav=document.querySelector('.sidebar nav');
 function showCurrentSidebarTab(){if(!sidebarNav||!window.matchMedia('(max-width:900px)').matches)return;const active=sidebarNav.querySelector('a.active');if(!active||sidebarNav.scrollWidth<=sidebarNav.clientWidth)return;const a=active.getBoundingClientRect(),n=sidebarNav.getBoundingClientRect();sidebarNav.scrollLeft+=a.left-n.left-(sidebarNav.clientWidth-a.width)/2;}
 window.requestAnimationFrame(showCurrentSidebarTab);window.addEventListener('resize',showCurrentSidebarTab);
 const params=new URLSearchParams(location.search),search=document.getElementById('board-search'),note=document.getElementById('search-note');
 if(search&&params.has('q')){search.value=params.get('q')||'';if(search.value.trim()&&note){note.hidden=false;note.textContent='“'+search.value+'” 검색 결과입니다. ';const a=document.createElement('a');a.href=location.pathname;a.textContent='전체 보기';a.style.textDecoration='underline';note.appendChild(a);}}
 const form=document.getElementById('inquiry-form');
 if(form){const type=form.elements.namedItem('type');if(params.has('type')&&Array.from(type.options).some(function(o){return o.value===params.get('type');}))type.value=params.get('type');
 form.addEventListener('submit',async function(e){e.preventDefault();if(!form.reportValidity())return;const submit=form.querySelector('button[type=submit]'),result=document.getElementById('form-result'),label=submit.querySelector('span'),data=new FormData(form);submit.disabled=true;label.textContent='접수 중입니다';result.hidden=true;result.classList.remove('error');form.setAttribute('aria-busy','true');
 try {const payload={type:data.get('type'),name:data.get('name'),email:data.get('email'),organization:data.get('organization')||'',subject:data.get('subject'),message:data.get('message'),consent:data.get('consent')==='on',website:data.get('website')||''};const response=await fetch('/api/inquiries',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(payload)});let body={};try{body=await response.json();}catch(_){}if(!response.ok||body.success===false||body.ok===false||body.error){const serverError=typeof body.error==='string'?body.error:typeof body.message==='string'?body.message:'';throw new Error(serverError||(response.status===429?'접수 요청이 많습니다. 잠시 후 다시 시도해 주세요.':'접수하지 못했습니다. 입력 내용을 확인하고 다시 시도해 주세요.'));}result.textContent='문의가 정상적으로 접수되었습니다. 내용을 확인한 뒤 입력하신 이메일로 안내드리겠습니다.';form.reset();result.hidden=false;result.focus();}
 catch(error){result.textContent=error instanceof TypeError?'연결이 원활하지 않습니다. 접수 여부를 확인할 수 없으니 잠시 후 다시 시도해 주세요.':error.message||'오류가 발생했습니다. 잠시 후 다시 시도해 주세요.';result.classList.add('error');result.hidden=false;result.focus();}
 finally{submit.disabled=false;label.textContent='문의 접수하기';form.removeAttribute('aria-busy');}});
 }
})();
`;
export function renderPage({path='/',pages=[],posts=[],detail=null}={}) {
 const route=canonicalPath(String(path).split('?')[0].replace(/\/+$/,'')||'/');
 const cleanPages=Array.isArray(pages)?pages:[];const cleanPosts=Array.isArray(posts)?posts:[];
 const title=route==='/'?'정원에서 희망을, ESG에서 미래를':route==='/village'?villageMeta.title:detail?.title||cleanPages.find(p=>p.path===route)?.title||({'/contact':'문의하기','/terms':'이용약관','/privacy':'개인정보처리방침','/404':'페이지를 찾을 수 없습니다'}[route])||'페이지 안내';
 const desc=route==='/'?'정원은 환경·사회·거버넌스를 통합하는 공익플랫폼입니다. 대한민국 ESG정원정책포럼은 정책과 실천, 도시와 기업, 시민을 연결합니다.':route==='/village'?villageMeta.desc:detail?plain(detail.body).slice(0,155):`${title} | 대한민국 ESG정원정책포럼`;
 return `<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#173d2d"><title>${E(title)} | 대한민국 ESG정원정책포럼</title><meta name="description" content="${E(desc)}"><meta property="og:type" content="${detail?'article':'website'}"><meta property="og:locale" content="ko_KR"><meta property="og:site_name" content="대한민국 ESG정원정책포럼"><meta property="og:title" content="${E(title)}"><meta property="og:description" content="${E(desc)}"><meta property="og:image" content="/assets/2b38d1e346508.jpg"><link rel="icon" type="image/svg+xml" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 48 48'%3E%3Crect width='48' height='48' rx='8' fill='%23173d2d'/%3E%3Cpath d='M24 41V24C8 26 9 12 9 8c14 0 19 7 15 19C23 12 33 7 41 8c0 12-6 19-17 17' stroke='%23d4ec92' fill='none' stroke-width='2'/%3E%3C/svg%3E"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>${route==='/'?'<link rel="preload" as="image" href="/assets/2b38d1e346508.jpg">':''}<style>${styles}\n${homeV2Styles}\n${originalLayoutStyles}
${headerV4Styles}
${designV4Styles}</style></head><body id="top" class="design-v4">${navigation(detail?'/'+postCategory(detail.category):route)}${route==='/'?homeV2(cleanPosts):route==='/village'?villageMain(groups):interior(route,cleanPages,cleanPosts,detail)}${footer()}<script>${headerV4Script}
${script}
${analyticsClientScript}</script></body></html>`;
}
